package com.example.microsave.repayment.service;
import com.example.microsave.exception.*;import com.example.microsave.loan.entity.Loan;import com.example.microsave.loan.repository.LoanRepository;import com.example.microsave.repayment.dto.RepaymentDTO;import com.example.microsave.repayment.entity.Repayment;import com.example.microsave.repayment.repository.RepaymentRepository;import java.math.BigDecimal;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service@Transactional public class RepaymentService{private final RepaymentRepository repo;private final LoanRepository loans;public RepaymentService(RepaymentRepository r,LoanRepository l){repo=r;loans=l;}private Repayment get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Repayment not found: "+id));}private Loan loan(Long id){return loans.findById(id).orElseThrow(()->new ResourceNotFoundException("Loan not found: "+id));}private RepaymentDTO map(Repayment r){return new RepaymentDTO(r.getId(),r.getLoan().getId(),r.getAmount(),r.getRepaymentDate(),r.getPaymentMethod(),r.getRemarks());}public List<RepaymentDTO>all(){return repo.findAll().stream().map(this::map).toList();}public List<RepaymentDTO>byLoan(Long id){loan(id);return repo.findByLoan_Id(id).stream().map(this::map).toList();}public RepaymentDTO one(Long id){return map(get(id));}
 private void adjust(Loan l,BigDecimal delta){BigDecimal next=l.getOutstandingAmount().add(delta);if(next.signum()<0)throw new BusinessRuleException("Repayment amount exceeds the outstanding loan amount.");l.setOutstandingAmount(next);l.setStatus(next.signum()==0?"CLOSED":"ACTIVE");}
 public RepaymentDTO create(RepaymentDTO d){Loan l=loan(d.loanId());if(d.amount().compareTo(l.getOutstandingAmount())>0)throw new BusinessRuleException("Repayment amount exceeds the outstanding loan amount.");Repayment r=new Repayment();r.setLoan(l);r.setAmount(d.amount());r.setRepaymentDate(d.repaymentDate());r.setPaymentMethod(d.paymentMethod());r.setRemarks(d.remarks());adjust(l,d.amount().negate());repo.save(r);return map(r);}
 public RepaymentDTO update(Long id,RepaymentDTO d){Repayment r=get(id);Loan old=r.getLoan();adjust(old,r.getAmount());Loan target=loan(d.loanId());if(d.amount().compareTo(target.getOutstandingAmount())>0)throw new BusinessRuleException("Repayment amount exceeds the outstanding loan amount.");r.setLoan(target);r.setAmount(d.amount());r.setRepaymentDate(d.repaymentDate());r.setPaymentMethod(d.paymentMethod());r.setRemarks(d.remarks());adjust(target,d.amount().negate());return map(repo.save(r));}
 public void delete(Long id){Repayment r=get(id);adjust(r.getLoan(),r.getAmount());repo.delete(r);}}
